test proverb-1 "zero pieces" -body {
    recite {}
} -returnCodes ok -match orderedLists -result {}

skip proverb-2
test proverb-2 "one piece" -body {
    recite { nail }
} -returnCodes ok -match orderedLists -result { "And all for the want of a nail." }

